import java.util.*;

/** Confirms each timeOfDay runs exactly one action after the break fix. */
public class ActProbe {
    static class T extends Actor {
        final List<String> calls = new ArrayList<>();
        T(Field f, Location l){ super(f, l); }
        protected void dayAct(List<Actor> n){ calls.add("day"); }
        protected void nightAct(List<Actor> n){ calls.add("night"); }
        protected double getFoodValue(){ return 0; }
        protected void setWeatherEffects(){ }
    }
    public static void main(String[] a){
        T day = new T(new Field(1,1), new Location(0,0));
        day.act(new ArrayList<>(), 0, Weather.SUNNY);
        T night = new T(new Field(1,1), new Location(0,0));
        night.act(new ArrayList<>(), 1, Weather.SUNNY);
        System.out.println("timeOfDay=0 -> " + day.calls + "   (expect [day], OLD bug gave [day, night])");
        System.out.println("timeOfDay=1 -> " + night.calls + " (expect [night])");
        boolean ok = day.calls.equals(List.of("day")) && night.calls.equals(List.of("night"));
        System.out.println("FIX_CORRECT=" + ok);
    }
}
